package vn.edu.eaut.lab7.repository; import vn.edu.eaut.lab7.model.*; import java.util.*; public class DiemRepository { private static final List<DiemSinhVien> data=new ArrayList<>(List.of(new DiemSinhVien(1,"SV001","Nguyễn Văn An",8,7,9),new DiemSinhVien(2,"SV002","Trần Thị Bình",9,8,8))); private static int next=3; public List<DiemSinhVien> findAll(){return data;} public DiemSinhVien findById(int id){return data.stream().filter(x->x.getId()==id).findFirst().orElse(null);} public void add(DiemSinhVien x){x.setId(next++);data.add(x);} public void update(DiemSinhVien x){DiemSinhVien o=findById(x.getId());if(o!=null){o.setMaSinhVien(x.getMaSinhVien());o.setHoTen(x.getHoTen());o.setChuyenCan(x.getChuyenCan());o.setGiuaKy(x.getGiuaKy());o.setCuoiKy(x.getCuoiKy());}} public void delete(int id){data.removeIf(x->x.getId()==id);} }